/*
 * BACK TO SCHOOL 10 — SCHOOL OPENS / CONNECTED LEARNING CAMPUS
 * Pure Canvas 2D; one continuous 25-second scene. Time is in SECONDS.
 * Standalone entry point: draw(ctx, time, width, height).
 * Export target: 3840x2160, 60 fps, CBR 100,000,000 bits/second.
 * The video encoder controls bitrate; Canvas only draws the frames.
 * Revision: paired window cues, rigid sliding doors, and one continuous entry flow.
 * Every pose is derived from time; frame order and frame rate do not affect it.
 */
function draw(ctx, time, width, height) {
  const duration = 25;
  if (!Number.isFinite(time) || !Number.isFinite(width) ||
      !Number.isFinite(height) || width <= 0 || height <= 0) return;

  const loopT = ((time % duration) + duration) % duration;
  const minSide = Math.min(width, height);

  const TAU = Math.PI * 2;
  const cycle = loopT / duration;
  const phase = TAU * cycle;
  const unit = minSide / 1000;
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const smooth = (a, b, v) => {
    const p = clamp((v - a) / (b - a), 0, 1);
    // Roundoff near a phase boundary must not create out-of-range opacity.
    return clamp(p * p * p * (p * (p * 6 - 15) + 10), 0, 1);
  };
  const envelope = (a, b, c, d) =>
    smooth(a, b, loopT) * (1 - smooth(c, d, loopT));

  function rounded(x, y, w, h, r) {
    r = Math.min(Math.max(r, 0), w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
  }
  function box(x, y, w, h, r, color) {
    if (w <= 0 || h <= 0) return;
    rounded(x, y, w, h, r);
    ctx.fillStyle = color;
    ctx.fill();
  }
  function line(points, color, weight) {
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++)
      ctx.lineTo(points[i][0], points[i][1]);
    ctx.strokeStyle = color;
    ctx.lineWidth = weight;
    ctx.stroke();
  }
  function circle(x, y, radius, color) {
    ctx.beginPath();
    ctx.arc(x, y, radius, 0, TAU);
    ctx.fillStyle = color;
    ctx.fill();
  }
  function gradient(x1, y1, x2, y2, stops) {
    const g = ctx.createLinearGradient(x1, y1, x2, y2);
    for (const stop of stops) g.addColorStop(stop[0], stop[1]);
    return g;
  }
  function text(value, x, y, size, weight, color, align) {
    ctx.font = weight + ' ' + size + 'px Arial, Helvetica, "DejaVu Sans", sans-serif';
    ctx.textAlign = align || 'left';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = color;
    ctx.fillText(value, x, y);
  }
  // One school day: lights on, doors open, entry flow, doors close, lights off.
  // Quintic easing gives zero velocity and acceleration at every door stop.
  const doorOpen = envelope(3.0, 6.0, 17.2, 20.5);
  const pathActive = envelope(6.2, 7.4, 15.5, 16.8);
  const doorway = {x: -84, y: -44, w: 168, h: 236, r: 9};
  const doorTravel = 84; // Fully concealed behind the jamb at the open hold.

  // One route and one speed across the walkway, steps and open doorway.
  // Wraps occur only at the faded endpoints, never as a visible position jump.
  const flowStartY = 334;
  const flowEndY = 48;
  const flowLength = flowStartY - flowEndY;
  const flowSpeed = 36; // Design units per second, independent of output size/fps.
  const flowDistance = (loopT - 6.2) * flowSpeed;
  // A time-lapse school day: 12 hours per loop, with a true 12:1 hand ratio.
  const hourAngle = -Math.PI / 2 + (8 / 12) * TAU + phase;
  const minuteAngle = -Math.PI / 2 + phase * 12;

  ctx.save();
  try {
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.globalAlpha = 1;
    ctx.globalCompositeOperation = 'source-over';
    ctx.shadowBlur = 0;
    ctx.shadowColor = 'rgba(0,0,0,0)';
    ctx.shadowOffsetX = 0;
    ctx.shadowOffsetY = 0;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.setLineDash([]);
    ctx.lineDashOffset = 0;

    // Linear dark gradient only. Window activity uses flat fills, never glow.
    ctx.fillStyle = gradient(0, height, width, 0,
      [[0, '#12212f'], [0.5, '#1b2c3c'], [1, '#2e2d43']]);
    ctx.fillRect(0, 0, width, height);
    ctx.translate(width / 2, height / 2 - 9 * unit);
    ctx.scale(unit, unit);

    // Ground and entrance walkway are geometric, flat shapes.
    line([[-431, 228], [431, 228]], '#4e6e80', 3);
    box(-53, 238, 106, 116, 12, '#385a70');
    box(-35, 253, 70, 86, 8, '#41667a');
    line([[0, 258], [0, 334]], '#638691', 2);

    // Symmetric classroom wings use the same dimensions and margin system.
    box(-382, -149, 244, 363, 10,
      gradient(-382, -149, -138, 214, [[0, '#7fa2ae'], [1, '#688fa0']]));
    box(138, -149, 244, 363, 10,
      gradient(138, -149, 382, 214, [[0, '#7fa2ae'], [1, '#688fa0']]));
    box(-393, -163, 255, 19, 6, '#4b6d86');
    box(138, -163, 255, 19, 6, '#4b6d86');
    line([[-377, 9], [-149, 9]], '#5b8296', 2);
    line([[149, 9], [377, 9]], '#5b8296', 2);

    // Mirrored pairs share their cue. Each sill, crossbar and grille uses
    // its window's center instead of a separate, slightly offset coordinate.
    const windowPositions = [];
    for (let row = 0; row < 2; row++) {
      for (let column = 0; column < 2; column++) {
        const rightX = 175 + column * 98;
        const rank = row * 2 + column;
        windowPositions.push(
          {x: -rightX - 76, y: -106 + row * 148, rank, side: -1},
          {x: rightX, y: -106 + row * 148, rank, side: 1}
        );
      }
    }
    for (const win of windowPositions) {
      const reverseRank = 3 - win.rank;
      const active = envelope(0.7 + win.rank * 0.65, 2.7 + win.rank * 0.65,
        18.2 + reverseRank * 0.3, 21.0 + reverseRank * 0.25);
      box(win.x, win.y, 76, 86, 8, '#365b72');
      box(win.x + 7, win.y + 7, 62, 72, 3, '#7b9da7');
      ctx.save();
      ctx.globalAlpha = active;
      box(win.x + 7, win.y + 7, 62, 72, 3,
        win.side < 0 ? '#dfc398' : '#b8d4c3');
      ctx.restore();
      box(win.x + 36.5, win.y + 7, 3, 72, 1.5, '#486c7d');
      box(win.x + 7, win.y + 41.5, 62, 3, 1.5, '#486c7d');
      box(win.x - 4, win.y + 92, 84, 7, 3, '#9bb7bd');
    }
    for (const win of windowPositions) {
      if (win.y !== 42) continue;
      const xx = win.x + 2;
      box(xx, 175, 72, 16, 4, '#5f879b');
      for (let i = 0; i < 4; i++)
        box(xx + 10 + i * 14, 180, 8, 2, 1, '#8babb5');
    }

    // Center facade and two fixed pilasters.
    box(-149, -208, 298, 423, 9,
      gradient(-149, -208, 149, 215, [[0, '#a4bec4'], [1, '#87aab6']]));
    box(-149, -198, 17, 404, 4, '#7399a9');
    box(132, -198, 17, 404, 4, '#7399a9');

    // Central gable: a precise flat triangle, without perspective shading.
    ctx.beginPath();
    ctx.moveTo(0, -334);
    ctx.lineTo(175, -199);
    ctx.lineTo(-175, -199);
    ctx.closePath();
    ctx.fillStyle = '#4f7188';
    ctx.fill();
    ctx.beginPath();
    ctx.moveTo(0, -318);
    ctx.lineTo(151, -209);
    ctx.lineTo(-151, -209);
    ctx.closePath();
    ctx.fillStyle = '#a5bfc3';
    ctx.fill();

    // Clock geometry is fixed; the two hands rotate around the exact same pin.
    const clockX = 0;
    const clockY = -254;
    circle(clockX, clockY, 31, '#5b7c8c');
    circle(clockX, clockY, 27, '#e3e6d7');
    for (let i = 0; i < 12; i++) {
      const a = i * TAU / 12 - Math.PI / 2;
      line([[clockX + Math.cos(a) * 21, clockY + Math.sin(a) * 21],
        [clockX + Math.cos(a) * 24, clockY + Math.sin(a) * 24]], '#718b92', 1);
    }
    line([[clockX, clockY], [clockX + Math.cos(hourAngle) * 12,
      clockY + Math.sin(hourAngle) * 12]], '#34536c', 3);
    line([[clockX, clockY], [clockX + Math.cos(minuteAngle) * 18,
      clockY + Math.sin(minuteAngle) * 18]], '#476c83', 2);
    circle(clockX, clockY, 2.6, '#34536c');

    box(-107, -192, 214, 40, 8, '#dbe1d4');
    text('SCHOOL', 0, -172, 21, '700', '#4f7280', 'center');

    // Cards update in a short, ordered sequence after the doors have opened.
    // Only the progress fill grows; each card and its padding stay fixed.
    box(-93, -125, 186, 42, 9, '#5f8498');
    const noticeColors = ['#b7cfc4', '#d7bf9c', '#b5c2d8'];
    for (let i = 0; i < 3; i++) {
      const xx = -77 + i * 56;
      box(xx, -117, 42, 26, 5, '#7899a8');
      const p = smooth(7.4 + i * 0.75, 8.9 + i * 0.75, loopT);
      const noticeVisible = 1 - smooth(18.3 + i * 0.25, 20.0 + i * 0.25, loopT);
      box(xx + 7, -109, 28, 3, 1.5, '#9db6bd');
      box(xx + 7, -101, 28, 2, 1, '#94aeb8');
      ctx.save();
      ctx.globalAlpha = noticeVisible;
      box(xx + 7, -109, 28 * p, 3, 1.5, noticeColors[i]);
      ctx.restore();
    }

    // Door panels translate rigidly into their side pockets within this mask.
    box(-99, -60, 198, 272, 15, '#41647b');
    ctx.save();
    rounded(doorway.x, doorway.y, doorway.w, doorway.h, doorway.r);
    ctx.clip();
    box(doorway.x, doorway.y, doorway.w, doorway.h, doorway.r, '#28485e');
    line([[-67, -21], [67, -21]], '#4e7082', 2);
    line([[-66, 163], [66, 163]], '#57788a', 2);
    box(-82, 177, 164, 15, 3, '#5b7c8e');
    ctx.save();
    ctx.globalAlpha = pathActive;
    line([[0, 173], [0, 48]], '#6c9b9a', 2);
    ctx.restore();

    for (const side of [-1, 1]) {
      const xx = side < 0 ? -83 - doorTravel * doorOpen : 1 + doorTravel * doorOpen;
      box(xx, -43, 82, 234, 5,
        gradient(xx, -43, xx + 82, 191, [[0, '#97bdc6'], [1, '#729daf']]));
      box(xx + 6, -34, 70, 57, 3, '#9ec4c9');
      box(xx + 6, 35, 70, 4, 2, '#c0d4d2');
      const handleX = side < 0 ? xx + 63 : xx + 15;
      box(handleX, 76, 4, 29, 2, '#d3dfd7');
      line([[xx + 9, 146], [xx + 73, 146]], '#8bb2bc', 1.5);
    }
    ctx.restore();

    // Foundation, threshold and walkway connect without loose or floating edges.
    box(-400, 210, 800, 18, 7, '#42647b');
    box(-131, 210, 262, 15, 5, '#7292a3');
    box(-151, 225, 302, 16, 5, '#5d7f94');
    line([[-120, 216], [120, 216]], '#9ab4bc', 1.5);

    // The short connector intentionally follows the central steps. It joins
    // the two existing path sections without a speed change or a particle reset.
    // Flow is visible only during the fully open door hold (6.2--16.8 seconds).
    ctx.save();
    ctx.globalAlpha = pathActive;
    line([[0, 258], [0, 173]], '#6c9b9a', 2);
    for (let i = 0; i < 4; i++) {
      const offset = flowDistance + i * flowLength / 4;
      const distance = ((offset % flowLength) + flowLength) % flowLength;
      const alpha = smooth(0, 20, distance) *
        (1 - smooth(flowLength - 20, flowLength, distance));
      ctx.save();
      ctx.globalAlpha *= alpha;
      circle(0, flowStartY - distance, 3.4, '#b8d2c2');
      ctx.restore();
    }
    ctx.restore();
  } finally {
    ctx.restore();
  }
}

draw.duration = 25;
draw.fps = 60;
draw.loop = true;
draw.exportSettings = Object.freeze({
  width: 3840,
  height: 2160,
  duration: 25,
  fps: 60,
  bitrate: 100000000,
  minBitrate: 100000000,
  maxBitrate: 100000000,
  rateControl: 'CBR'
});

/*
 * BACK TO SCHOOL 09 — OPEN KNOWLEDGE / GUIDED READING BOOK
 * Pure Canvas 2D; one continuous 25-second scene. Time is in SECONDS.
 * Standalone entry point: draw(ctx, time, width, height).
 * Export target: 3840x2160, 60 fps, CBR 100,000,000 bits/second.
 * The video encoder controls bitrate; Canvas only draws the frames.
 */
function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 1;
  const loopT = ((t % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  if (!(minSide > 0) || !Number.isFinite(t)) return;

  const TAU = Math.PI * 2;
  const cycle = (currentScene + sceneProgress) / sceneCount;
  const unit = minSide / 900;
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const smooth = (a, b, v) => {
    const p = clamp((v - a) / (b - a), 0, 1);
    return p * p * p * (p * (p * 6 - 15) + 10);
  };
  const progress = (a, b) => smooth(a, b, loopT);
  const envelope = (a, b, c, d) => progress(a, b) * (1 - progress(c, d));

  function rounded(x, y, w, h, r) {
    r = Math.min(Math.max(r, 0), w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
  }
  function box(x, y, w, h, r, color) {
    if (w <= 0 || h <= 0) return;
    rounded(x, y, w, h, r);
    ctx.fillStyle = color;
    ctx.fill();
  }
  function line(points, color, weight) {
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++)
      ctx.lineTo(points[i][0], points[i][1]);
    ctx.strokeStyle = color;
    ctx.lineWidth = weight;
    ctx.stroke();
  }
  function circle(x, y, radius, color) {
    ctx.beginPath();
    ctx.arc(x, y, radius, 0, TAU);
    ctx.fillStyle = color;
    ctx.fill();
  }
  function gradient(x1, y1, x2, y2, stops) {
    const g = ctx.createLinearGradient(x1, y1, x2, y2);
    for (const stop of stops) g.addColorStop(stop[0], stop[1]);
    return g;
  }
  function text(value, x, y, size, weight, color, align) {
    ctx.font = weight + ' ' + size + 'px Arial, Helvetica, "DejaVu Sans", sans-serif';
    ctx.textAlign = align || 'left';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = color;
    ctx.fillText(value, x, y);
  }
  function partialPath(points, amount, color, weight) {
    amount = clamp(amount, 0, 1);
    if (amount <= 0) return;
    const lengths = [];
    let total = 0;
    for (let i = 1; i < points.length; i++) {
      const length = Math.hypot(points[i][0] - points[i - 1][0],
        points[i][1] - points[i - 1][1]);
      lengths.push(length);
      total += length;
    }
    let remaining = total * amount;
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) {
      const length = lengths[i - 1];
      const p = Math.min(1, remaining / length);
      ctx.lineTo(points[i - 1][0] + (points[i][0] - points[i - 1][0]) * p,
        points[i - 1][1] + (points[i][1] - points[i - 1][1]) * p);
      remaining -= length;
      if (remaining <= 0) break;
    }
    ctx.strokeStyle = color;
    ctx.lineWidth = weight;
    ctx.stroke();
  }
  function pathPoint(points, p) {
    const lengths = [];
    let total = 0;
    for (let i = 1; i < points.length; i++) {
      const length = Math.hypot(points[i][0] - points[i - 1][0],
        points[i][1] - points[i - 1][1]);
      lengths.push(length);
      total += length;
    }
    let distance = clamp(p, 0, 1) * total;
    for (let i = 1; i < points.length; i++) {
      if (distance <= lengths[i - 1]) {
        const q = distance / lengths[i - 1];
        return {x: points[i - 1][0] + (points[i][0] - points[i - 1][0]) * q,
          y: points[i - 1][1] + (points[i][1] - points[i - 1][1]) * q};
      }
      distance -= lengths[i - 1];
    }
    return {x: points[points.length - 1][0], y: points[points.length - 1][1]};
  }
  function tick(x, y, amount, color) {
    partialPath([[x - 5, y], [x - 1, y + 4], [x + 7, y - 5]], amount, color, 2);
  }
  function leftPage() {
    ctx.beginPath();
    ctx.moveTo(-16, -230);
    ctx.bezierCurveTo(-105, -263, -248, -264, -350, -240);
    ctx.quadraticCurveTo(-365, -237, -365, -219);
    ctx.lineTo(-365, 221);
    ctx.quadraticCurveTo(-365, 241, -346, 243);
    ctx.bezierCurveTo(-240, 220, -112, 220, -16, 254);
    ctx.closePath();
  }

  const reset = 1 - progress(21.6, 24.6);
  const scroll = 14 * envelope(21.0, 22.2, 23.2, 24.6);
  const leftRows = [-135, -111, -87, -63, -39];
  const leftWidths = [238, 217, 250, 188, 231];
  const rightRows = [-135, -111, -87, -63, -39, 13, 37, 61];
  const rightWidths = [249, 211, 235, 188, 244, 227, 249, 195];
  const leftScans = leftRows.map((_, i) => progress(0.6 + i * 1.35, 1.95 + i * 1.35) * reset);
  const rightScans = rightRows.map((_, i) => progress(14 + i * 0.85, 14.85 + i * 0.85) * reset);
  const diagramProgress = progress(8.0, 11.5) * reset;
  const readingProgress = (leftScans.reduce((a, b) => a + b, 0)
    + rightScans.reduce((a, b) => a + b, 0) + 3 * diagramProgress) / 16;
  const bookmarkTop = -266 + 72 * readingProgress;
  const leftPath = [[-194, 85], [-194, 100], [-278, 100], [-278, 117]];
  const rightPath = [[-194, 85], [-194, 100], [-110, 100], [-110, 117]];

  ctx.save();
  try {
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.globalAlpha = 1;
    ctx.globalCompositeOperation = 'source-over';
    ctx.shadowBlur = 0;
    ctx.shadowColor = 'rgba(0,0,0,0)';
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.setLineDash([]);
    ctx.lineDashOffset = 0;

    // Contemporary dark linear gradient, without glow, blur or particles.
    ctx.fillStyle = gradient(0, height, width, 0,
      [[0, '#142130'], [0.5, '#1b303a'], [1, '#2b2d46']]);
    ctx.fillRect(0, 0, width, height);
    ctx.translate(width / 2, height / 2 - 4 * unit);
    ctx.scale(unit, unit);

    // Open-book cover is a two-dimensional silhouette, without perspective.
    ctx.beginPath();
    ctx.moveTo(0, -220);
    ctx.bezierCurveTo(-105, -277, -275, -275, -382, -247);
    ctx.quadraticCurveTo(-395, -242, -395, -222);
    ctx.lineTo(-395, 249);
    ctx.quadraticCurveTo(-395, 267, -374, 270);
    ctx.bezierCurveTo(-248, 245, -100, 244, 0, 284);
    ctx.bezierCurveTo(100, 244, 248, 245, 374, 270);
    ctx.quadraticCurveTo(395, 267, 395, 249);
    ctx.lineTo(395, -222);
    ctx.quadraticCurveTo(395, -242, 382, -247);
    ctx.bezierCurveTo(275, -275, 105, -277, 0, -220);
    ctx.closePath();
    ctx.fillStyle = gradient(-395, -250, 395, 284,
      [[0, '#658494'], [0.5, '#50778a'], [1, '#3d657c']]);
    ctx.fill();

    leftPage();
    ctx.fillStyle = gradient(-365, -240, -16, 254,
      [[0, '#e9e7db'], [1, '#dbe3d7']]);
    ctx.fill();
    ctx.save();
    ctx.scale(-1, 1);
    leftPage();
    ctx.fillStyle = gradient(-365, -240, -16, 254,
      [[0, '#e3e8dc'], [1, '#d1e0d5']]);
    ctx.fill();
    ctx.restore();

    // Headers have separate, permanent safe margins.
    text('KNOWLEDGE', -327, -201, 17, '700', '#527880');
    text('01', -58, -201, 10, '700', '#87a29e', 'right');
    line([[-327, -177], [-58, -177]], '#b5c9bd', 1.2);
    text('DISCOVER', 58, -201, 17, '700', '#527880');
    text('02', 327, -201, 10, '700', '#87a29e', 'right');
    line([[58, -177], [327, -177]], '#b5c9bd', 1.2);

    // Left content scrolls only fourteen units and never reaches the header.
    ctx.save();
    ctx.beginPath();
    ctx.rect(-337, -160, 288, 331);
    ctx.clip();
    ctx.translate(0, -scroll);
    for (let i = 0; i < leftRows.length; i++) {
      const yy = leftRows[i];
      const q = leftScans[i];
      ctx.save();
      ctx.globalAlpha = 0.67;
      box(-333, yy - 8, (leftWidths[i] + 12) * q, 20, 6, '#bfd7bd');
      ctx.restore();
      box(-327, yy, leftWidths[i], 4.5, 2.25, '#8ca69f');
      if (q > 0.00001) box(-327, yy + 8, leftWidths[i] * q, 2.5, 1.25, '#699991');
    }

    // A compact learning diagram occupies a dedicated panel below the paragraph.
    box(-334, 22, 284, 141, 12, '#cadbd0');
    text('CONNECT THE IDEAS', -320, 38, 8, '700', '#71928a');
    ctx.save();
    ctx.globalAlpha = reset;
    partialPath(leftPath, progress(8.8, 10.2), '#7ca69c', 2);
    partialPath(rightPath, progress(9.6, 10.9), '#7ca69c', 2);
    ctx.restore();

    const diagramNodes = [
      {x: -194, y: 70, a: envelope(8.0, 8.8, 21.6, 24.6), c: '#8fb9ab', kind: 0},
