/*
 * BACK TO SCHOOL 02 — STUDY SYSTEM / MODULAR LEARNING NOTEBOOK
 * One continuous 25-second scene. Pure Canvas 2D. Time is in SECONDS.
 * Standalone entry point: draw(ctx, time, width, height).
 * Suggested export: UHD 3840x2160, 60 fps, CBR 100,000,000 bits/second.
 * The video encoder must enforce bitrate; Canvas only draws the frames.
 */
function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 1;
  const loopT = ((t % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  if (!(minSide > 0) || !Number.isFinite(t)) return;

  const TAU = Math.PI * 2;
  const cycle = (currentScene + sceneProgress) / sceneCount;
  const phase = cycle * TAU;
  const unit = minSide / 1000;
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const smooth = (a, b, v) => {
    const q = clamp((v - a) / (b - a), 0, 1);
    return q * q * q * (q * (q * 6 - 15) + 10);
  };
  const envelope = (a, b, c, d) =>
    smooth(a, b, loopT) * (1 - smooth(c, d, loopT));

  function rounded(x, y, w, h, r) {
    r = Math.min(Math.max(r, 0), w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
  }
  function box(x, y, w, h, r, color) {
    rounded(x, y, w, h, r);
    ctx.fillStyle = color;
    ctx.fill();
  }
  function line(points, color, weight) {
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++)
      ctx.lineTo(points[i][0], points[i][1]);
    ctx.strokeStyle = color;
    ctx.lineWidth = weight;
    ctx.stroke();
  }
  function gradient(x1, y1, x2, y2, stops) {
    const g = ctx.createLinearGradient(x1, y1, x2, y2);
    for (const stop of stops) g.addColorStop(stop[0], stop[1]);
    return g;
  }
  function text(value, x, y, size, weight, color, align) {
    ctx.font = weight + ' ' + size + 'px Arial, Helvetica, "DejaVu Sans", sans-serif';
    ctx.textAlign = align || 'left';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = color;
    ctx.fillText(value, x, y);
  }
  function tick(x, y, progress, size, color) {
    if (progress <= 0) return;
    ctx.save();
    ctx.translate(x, y);
    const pts = [[-size * 0.32, 0], [-size * 0.07, size * 0.24],
      [size * 0.36, -size * 0.27]];
    const split = 0.39;
    ctx.beginPath();
    ctx.moveTo(pts[0][0], pts[0][1]);
    if (progress < split) {
      const a = progress / split;
      ctx.lineTo(pts[0][0] + (pts[1][0] - pts[0][0]) * a,
        pts[0][1] + (pts[1][1] - pts[0][1]) * a);
    } else {
      const a = (progress - split) / (1 - split);
      ctx.lineTo(pts[1][0], pts[1][1]);
      ctx.lineTo(pts[1][0] + (pts[2][0] - pts[1][0]) * a,
        pts[1][1] + (pts[2][1] - pts[1][1]) * a);
    }
    ctx.lineWidth = 2.7;
    ctx.strokeStyle = color;
    ctx.stroke();
    ctx.restore();
  }

  // Three complete steps make the circular card track close exactly.
  const step1 = smooth(6.0, 9.1, loopT);
  const step2 = smooth(12.6, 15.9, loopT);
  const step3 = smooth(20.0, 24.3, loopT);
  const scroll = 126 * (step1 + step2 + step3);
  const progress = 0.24 + 0.62 * (0.5 - 0.5 * Math.cos(phase));
  const activity = [
    envelope(1.0, 3.8, 19.1, 21.3),
    envelope(3.0, 5.6, 18.5, 20.4),
    envelope(9.2, 11.8, 18.0, 19.8)
