    ctx.shadowColor = 'rgba(0,0,0,0)';
    ctx.setLineDash([]);
    ctx.lineDashOffset = 0;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    // A broad linear dark gradient only: no glow or radial lighting.
    ctx.fillStyle = gradient(0, height, width, 0, [
      [0, '#171d30'], [0.5, '#232239'], [1, '#302840']
    ]);
