    for (let i = 0; i < 4; i++) {
      const focus = Math.pow(0.5 + 0.5 * Math.cos(phase - i * TAU / 4), 5);
      const extension = 12 * focus;
      const yy = -211 + i * 111;
      box(212, yy, 69 + extension, 68, 11, tabColors[i]);
      line([[253 + extension, yy + 25], [265 + extension, yy + 25]],
