      text(names[index], -96, yy + 31, 15, '700', '#3e4c5c');
      text('0' + (index + 1), 144, yy + 30, 11, '700', color, 'right');
      text(descriptions[index], -96, yy + 52, 9.5, '500', '#78868a');

      // Two note rails; fill and tracking stay below the text baseline.
      box(-96, yy + 68, 206, 4, 2, '#dce2da');
      box(-96, yy + 68, 28 + 178 * fillAmount, 4, 2, tabColors[index]);
      box(-96, yy + 81, 151, 3, 1.5, '#e0e4db');
      const noteMarker = 0.5 - 0.5 * Math.cos(phase * 2 - index * 1.4);
      box(-95 + 137 * noteMarker, yy + 80, 12, 5, 2.5, color);

      // A contained mini diagram supports the note content.
      const diagramX = 130;
      const diagramY = yy + 66;
      line([[diagramX - 7, diagramY + 13], [diagramX + 5, diagramY],
        [diagramX + 17, diagramY + 13]], '#c1cbc4', 1.4);
      for (let n = 0; n < 3; n++) {
        const dx = diagramX - 7 + 12 * n;
        const dy = n === 1 ? diagramY : diagramY + 13;
